macro.command:
/**
 * RealityCollapse — Teleport (fixed parity snapping for multi-tile tokens)
 * - odd-sized tokens snap to cell center
 * - even-sized tokens snap to grid intersection (so their edges align with grid lines)
 * - only uses MidiQOL.moveToken(token, {x,y}, false)
 */

(async () => {
  const RANGE_FT = 120;
  const TIMEOUT_MS = 20000;
  const HIGHLIGHT_COLOR = 0x66ccff;

  // 選擇目標：優先 game.user.targets，再取 controlled
  const targets = Array.from(game.user.targets ?? []);
  const targetToken = (targets.length === 1) ? targets[0] : (canvas.tokens.controlled[0] ?? null);
  if (!targetToken) {
    return ui.notifications.warn("請先 target 或選中單個要傳送的目標，然後運行宏。");
  }

  const gs = canvas.grid.size;
  const feetPerSquare = canvas.scene.grid?.distance ?? 5;
  const maxSquares = Math.max(1, Math.floor(RANGE_FT / feetPerSquare));
  const radiusPx = maxSquares * gs;

  // token grid size (整數格數)
  const tokenGridW = Number(targetToken.document.width ?? targetToken.document._source?.width ?? 1);
  const tokenGridH = Number(targetToken.document.height ?? targetToken.document._source?.height ?? tokenGridW);

  // caster/anchor center: 把施法者定位留空（此宏仍以目標爲原點選擇，但可在需要時改爲以施法者爲中心）
  const originCenter = { x: (targetToken.center?.x ?? (targetToken.x + targetToken.w/2)), y: (targetToken.center?.y ?? (targetToken.y + targetToken.h/2)) };

  // 畫高亮圓
  const g = new PIXI.Graphics();
  g.lineStyle(2, HIGHLIGHT_COLOR, 0.9);
  g.beginFill(HIGHLIGHT_COLOR, 0.06);
  g.drawCircle(originCenter.x, originCenter.y, radiusPx);
  g.endFill();
  g.zIndex = 10000;
  canvas.app.stage.addChild(g);
  ui.notifications.info(`請在高亮區域內點擊落點（最多 ${RANGE_FT} 英尺）。點擊超出或佔用會提示並重選。`);

  // helper: snap to cell center using getSnappedPoint CENTER mode
  function snapToCellCenter(stagePoint) {
    try {
      return canvas.grid.getSnappedPoint({ x: stagePoint.x, y: stagePoint.y }, { mode: CONST.GRID_SNAPPING_MODES.CENTER, resolution: 1 });
    } catch (e) {
      return { x: Math.round(stagePoint.x / gs) * gs, y: Math.round(stagePoint.y / gs) * gs };
    }
  }

  // helper: snap to intersection (grid lines) -> intersection at integer multiples of gridSize
  function snapToGridIntersection(stagePoint) {
    const ix = Math.round(stagePoint.x / gs) * gs;
    const iy = Math.round(stagePoint.y / gs) * gs;
    return { x: ix, y: iy };
  }

  // 點擊偵聽（返回舞臺座標的 Point 或 null）
  const getClickStagePoint = (ms) => new Promise(resolve => {
    const handler = (event) => {
      try { canvas.app.stage.off("pointerdown", handler); } catch(e){}
      let pos = null;
      try { pos = event.data.getLocalPosition(canvas.app.stage); } catch(e) { pos = null; }
      resolve(pos ? { x: pos.x, y: pos.y } : null);
    };
    canvas.app.stage.on("pointerdown", handler);
    setTimeout(() => { try { canvas.app.stage.off("pointerdown", handler); } catch(e){}; resolve(null); }, ms);
  });

  // 檢查矩形是否被其它 Token 佔用（忽略 selfId）
  function rectOccupied(topLeftX, topLeftY, widthPx, heightPx, selfId=null) {
    const rectA = new PIXI.Rectangle(topLeftX, topLeftY, widthPx, heightPx);
    return canvas.tokens.placeables.some(t => {
      if (t.id === selfId) return false;
      const rectB = new PIXI.Rectangle(t.x, t.y, t.w, t.h);
      return rectA.right  > rectB.left &&
             rectA.left   < rectB.right &&
             rectA.bottom > rectB.top &&
             rectA.top    < rectB.bottom;
    });
  }

  // 主循環：強制直到選取合法落點
  while (true) {
    // 確保高亮在舞臺
    if (!canvas.app.stage.children.includes(g)) canvas.app.stage.addChild(g);

    const clicked = await getClickStagePoint(TIMEOUT_MS);
    if (!clicked) { ui.notifications.warn("未檢測到點擊，請再試一次"); continue; }

    // 根據 token 的寬高奇偶性選擇 snapping 策略
    // X 方向
    const snapX = (tokenGridW % 2 === 1) ? snapToCellCenter(clicked).x : snapToGridIntersection(clicked).x;
    // Y 方向
    const snapY = (tokenGridH % 2 === 1) ? snapToCellCenter(clicked).y : snapToGridIntersection(clicked).y;

    const snapped = { x: snapX, y: snapY };

    // 計算所選位置的 token left-top grid indices
    const clickedCol = Math.floor(snapped.x / gs);
    const clickedRow = Math.floor(snapped.y / gs);

    const topLeftCol = clickedCol - Math.floor(tokenGridW / 2);
    const topLeftRow = clickedRow - Math.floor(tokenGridH / 2);

    // 目標中心（舞臺座標）按 top-left + half-size
    const centerX = (topLeftCol + tokenGridW / 2) * gs;
    const centerY = (topLeftRow + tokenGridH / 2) * gs;

    // 距離檢查（以 originCenter 爲圓心）
    const distFt = Math.hypot(centerX - originCenter.x, centerY - originCenter.y) / gs * feetPerSquare;
    if (distFt > RANGE_FT + 0.001) {
      ui.notifications.warn(`選擇超出 ${RANGE_FT} 英尺（${Math.round(distFt)}ft），請重新選擇`);
      continue;
    }

    // 計算 top-left 像素用於碰撞檢測
    const destLeft = Math.round(topLeftCol * gs);
    const destTop  = Math.round(topLeftRow * gs);
    const destWpx  = tokenGridW * gs;
    const destHpx  = tokenGridH * gs;

    // 碰撞檢測
    if (rectOccupied(destLeft, destTop, destWpx, destHpx, targetToken.id)) {
      ui.notifications.warn("目標格被佔用，請選擇其它位置");
      continue;
    }

    // 清理高亮並執行瞬移（只用 MidiQOL.moveToken，傳入 center 座標）
    try { canvas.app.stage.removeChild(g); } catch(e){}
    if (typeof MidiQOL?.moveToken === "function") {
      try {
        await MidiQOL.moveToken(targetToken, { x: Math.round(centerX), y: Math.round(centerY) }, false);
        ui.notifications.info(`${targetToken.name} 已被傳送（無動畫）`);
        console.log(`RealityCollapse: teleported ${targetToken.name} -> center=${Math.round(centerX)},${Math.round(centerY)} topLeft=${destLeft},${destTop} grid=${tokenGridW}x${tokenGridH}`);
        return true;
      } catch (e) {
        console.error("RealityCollapse: MidiQOL.moveToken failed", e);
        ui.notifications.error("傳送失敗（查看控制檯）");
        return false;
      }
    } else {
      ui.notifications.error("MidiQOL.moveToken 不可用（宏僅使用它執行傳送）");
      return false;
    }
  }
})();
